fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    assert_eq!(dst.len(), src.len(), "dst and src must have the same length");
    assert_eq!(dst.len(), mask.len(), "mask must have the same length as dst/src");

    dst.into_iter()
        .zip(src.into_iter())
        .zip(mask.into_iter())
        .map(|((d, s), m)| if m { s } else { d })
        .collect()
}